const News: React.FC = () => {
  const [filter, setFilter] = useState<string>('All');
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const timer = setTimeout(() => setIsLoading(false), 800);
    return () => clearTimeout(timer);
  }, []);

  const filteredNews = useMemo(() => {
    return filter === 'All' 
      ? ALL_NEWS 
      : ALL_NEWS.filter(n => n.category === filter);
  }, [filter]);

  const shockNews = useMemo(() => {
    return ALL_NEWS.filter(n => n.category === 'Shock');
  }, []);

  const handleRipple = (e: React.MouseEvent<HTMLButtonElement>) => {
    (window as any).createRipple?.(e);
  };

  const categories = [
    { id: 'All', label: 'Todos' },
    { id: 'Shock', label: 'Shock Digital' },
    { id: 'AI', label: 'AI' },
    { id: 'Dev', label: 'Dev' },
    { id: 'Tech', label: 'Tech' },
    { id: 'Hardware', label: 'Hardware' }
  ];

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
      <div className="mb-12">
        <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 mb-8">
          <div>
            <h1 className="text-4xl font-bold text-white mb-4">Archivo de Noticias</h1>
            <p className="text-slate-400 max-w-2xl">Explora nuestra colección completa de artículos sobre IA, desarrollo y las noticias más impactantes del Shock Digital.</p>
          </div>

          <div className="flex flex-wrap gap-2">
            {categories.map(cat => (
              <button
                key={cat.id}
                onClick={(e) => {
                  setFilter(cat.id);
                  handleRipple(e);
                }}
                className={`ripple-container px-4 py-1.5 rounded-full text-sm font-medium transition-all border ${
                  filter === cat.id 
                    ? cat.id === 'Shock' ? 'bg-red-600 border-red-500 text-white' : 'bg-blue-600 border-blue-500 text-white'
                    : 'bg-[#161b22] border-[#30363d] text-slate-400 hover:border-[#8b949e]'
                }`}
              >
                {cat.label}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Special Highlight for Shock Digital when filtering 'All' or 'Shock' */}
      {(filter === 'All' || filter === 'Shock') && shockNews.length > 0 && !isLoading && (
        <section className="mb-16">
          <div className="flex items-center space-x-3 mb-8">
            <h2 className="text-xl font-bold text-red-500 uppercase tracking-[0.2em] flex items-center">
              <span className="w-3 h-3 bg-red-500 rounded-full mr-2 animate-ping"></span>
              Alerta: Shock Digital
            </h2>
            <div className="h-px bg-gradient-to-r from-red-500/50 to-transparent flex-grow"></div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            {shockNews.map(news => (
              <NewsCard key={news.id} news={news} />
            ))}
          </div>
        </section>
      )}

      {/* Main Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
        {isLoading ? (
          Array.from({ length: 6 }).map((_, i) => <NewsSkeleton key={i} />)
        ) : (
          filteredNews.filter(n => filter === 'Shock' || n.category !== 'Shock').map(news => (
            <NewsCard key={news.id} news={news} />
          ))
        )}
      </div>

      {!isLoading && filteredNews.length === 0 && (
        <div className="text-center py-20">
          <p className="text-slate-500 italic">No hay noticias en esta categoría por ahora.</p>
        </div>
      )}
