              <div className="flex-grow">
                <div className="flex items-center space-x-2 mb-1.5">
                  <span className="text-sm font-bold text-slate-200 group-hover:text-blue-400 transition-colors cursor-pointer">{comment.user}</span>
                  <span className="text-[10px] text-slate-500 font-mono tracking-tighter uppercase">{comment.date}</span>
