      <button
        onClick={handleScrollToTop}
        className={`fixed bottom-8 right-8 z-50 p-3.5 rounded-2xl bg-[#161b22] border border-[#30363d] text-slate-400 hover:text-blue-400 hover:border-blue-500/50 hover:bg-[#1f242c] transition-all duration-300 shadow-2xl ${
          showScrollTop ? 'translate-y-0 opacity-100 scale-100' : 'translate-y-12 opacity-0 scale-75 pointer-events-none'
