import React, { useState, useEffect, useRef } from 'react';
import { Link } from 'react-router-dom';
import { NewsItem } from '../types';

interface NewsCardProps {
  news: NewsItem;
}

const NewsCard: React.FC<NewsCardProps> = ({ news }) => {
  const [isVisible, setIsVisible] = useState(false);
  const [imageLoaded, setImageLoaded] = useState(false);
  const cardRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
          observer.unobserve(entry.target);
        }
      },
      { threshold: 0.1 }
    );

    if (cardRef.current) {
      observer.observe(cardRef.current);
    }

    return () => {
      if (cardRef.current) {
        observer.unobserve(cardRef.current);
      }
    };
  }, []);

  const getCategoryColor = (category: string) => {
    switch (category) {
      case 'AI': return 'bg-purple-900/40 text-purple-300 border-purple-500/30';
      case 'Dev': return 'bg-blue-900/40 text-blue-300 border-blue-500/30';
      case 'Tech': return 'bg-green-900/40 text-green-300 border-green-500/30';
      case 'Shock': return 'bg-red-950/60 text-red-400 border-red-500/40 animate-pulse';
      default: return 'bg-slate-800 text-slate-300 border-slate-600/30';
    }
  };

  return (
    <Link to={`/news/${news.id}`} className={`group h-full block ${news.category === 'Shock' ? 'relative z-10' : ''}`}>
      <div 
        ref={cardRef}
        className={`bg-[#0d1117] border rounded-xl overflow-hidden hover:border-[#8b949e] transition-all duration-300 flex flex-col h-full shadow-lg hover:shadow-blue-500/10 active:scale-[0.98] ${
          news.category === 'Shock' ? 'border-red-900/30 ring-1 ring-red-500/10' : 'border-[#30363d]'
        }`}
      >
        {/* Image Container */}
        <div className="relative h-52 overflow-hidden border-b border-[#30363d] bg-slate-900">
          {/* Shimmer Placeholder */}
          {!imageLoaded && <div className="absolute inset-0 z-0 shimmer" />}

          {/* Subtle Glow Overlay */}
          <div className="absolute inset-0 z-10 bg-gradient-to-t from-[#0d1117]/80 via-transparent to-transparent opacity-60 group-hover:opacity-40 transition-opacity" />

          <img 
            src={news.imageUrl} 
            alt={news.title} 
            loading="lazy"
            onLoad={() => setImageLoaded(true)}
            className={`w-full h-full object-cover transition-all duration-[1200ms] ease-out group-hover:scale-105 group-hover:brightness-110 group-hover:contrast-[1.05] ${
              isVisible && imageLoaded ? 'opacity-100 translate-y-0 scale-100' : 'opacity-0 translate-y-4 scale-110 blur-sm'
            }`}
          />

          {/* Top Tag */}
          <div className="absolute top-4 left-4 z-20">
            <span className={`text-[10px] font-bold px-2.5 py-1 rounded-md border backdrop-blur-md uppercase tracking-wider shadow-sm flex items-center ${getCategoryColor(news.category)}`}>
              {news.category === 'Shock' && <span className="w-1.5 h-1.5 bg-red-500 rounded-full mr-1.5 animate-ping"></span>}
              {news.category === 'Shock' ? 'SHOCK DIGITAL' : news.category}
            </span>
          </div>

          {/* Hover Shine Effect */}
          <div className="absolute inset-0 z-15 opacity-0 group-hover:opacity-100 transition-opacity duration-700 pointer-events-none bg-gradient-to-r from-transparent via-white/10 to-transparent skew-x-[-20deg] transform -translate-x-full group-hover:translate-x-[150%] transition-transform duration-1000 ease-in-out" />
        </div>

        {/* Content Section */}
        <div className={`p-6 flex flex-col flex-grow bg-gradient-to-b ${news.category === 'Shock' ? 'from-red-950/10 to-[#0d1117]' : 'from-[#161b22] to-[#0d1117]'}`}>
          <h3 className={`text-lg font-bold transition-colors leading-snug mb-3 ${news.category === 'Shock' ? 'text-white group-hover:text-red-400' : 'text-slate-100 group-hover:text-blue-400'}`}>
            {news.title}
          </h3>
          <p className="text-sm text-slate-400 line-clamp-2 mb-5 flex-grow leading-relaxed">
            {news.excerpt}
          </p>

          <div className="flex items-center justify-between mt-auto pt-4 border-t border-[#30363d]/50">
            <div className="flex items-center space-x-2">
              <div className={`w-6 h-6 rounded-full border flex items-center justify-center text-[10px] font-bold ${news.category === 'Shock' ? 'bg-red-600/20 border-red-500/30 text-red-400' : 'bg-blue-600/20 border-blue-500/30 text-blue-400'}`}>
                {news.author.charAt(0)}
              </div>
              <span className="text-xs text-slate-300 font-medium">{news.author}</span>
            </div>
            <div className="flex items-center text-xs text-slate-500 font-mono">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3 mr-1 opacity-70" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
              </svg>
              {news.date}
            </div>
          </div>
        </div>
      </div>
    </Link>
  );
};

export default NewsCard;

import React, { useState, useEffect, useMemo } from 'react';
import { useParams, Link, useNavigate, useLocation } from 'react-router-dom';
import { ALL_NEWS } from '../constants/newsData';
import { NewsItem } from '../types';
import { marked } from 'marked';
import NewsCard from '../components/NewsCard';

interface Comment {
  id: string;
  user: string;
  text: string;
  date: string;
}

const NewsDetailSkeleton = () => (
  <div className="animate-pulse">
    <div className="h-4 w-32 bg-[#161b22] rounded mb-8" />
    <div className="flex space-x-2 mb-4">
      <div className="h-5 w-16 bg-[#161b22] rounded" />
      <div className="h-5 w-24 bg-[#161b22] rounded" />
    </div>
    <div className="h-12 w-full bg-[#161b22] rounded mb-6" />
    <div className="h-12 w-3/4 bg-[#161b22] rounded mb-8" />

    <div className="flex justify-between items-center pb-8 border-b border-slate-800 mb-8">
      <div className="flex space-x-3 items-center">
        <div className="w-10 h-10 rounded-full bg-[#161b22]" />
        <div className="space-y-2">
          <div className="h-4 w-24 bg-[#161b22] rounded" />
          <div className="h-3 w-32 bg-[#161b22] rounded" />
        </div>
      </div>
      <div className="h-10 w-28 bg-[#161b22] rounded-lg" />
    </div>

    <div className="h-96 w-full bg-[#161b22] rounded-2xl mb-12" />

    <div className="space-y-4">
      <div className="h-4 w-full bg-[#161b22] rounded" />
      <div className="h-4 w-full bg-[#161b22] rounded" />
      <div className="h-4 w-5/6 bg-[#161b22] rounded" />
      <div className="h-4 w-full bg-[#161b22] rounded" />
    </div>
  </div>
);

const NewsDetail: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const location = useLocation();
  const [news, setNews] = useState<NewsItem | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [imageLoaded, setImageLoaded] = useState(false);
  const [showCopied, setShowCopied] = useState(false);
  const [showScrollTop, setShowScrollTop] = useState(false);
  const [isUserLoggedIn, setIsUserLoggedIn] = useState(false);
  const [currentUser, setCurrentUser] = useState<any>(null);

  const [comments, setComments] = useState<Comment[]>([
    { id: 'c1', user: 'TechEnthusiast', text: 'Excelente análisis. Esto cambia por completo las reglas del juego. **NVIDIA** está en otro nivel.', date: 'Hace 2 horas' },
    { id: 'c2', user: 'DevMaster', text: 'Me preocupa la eficiencia térmica de estos nuevos chips, pero el rendimiento es innegable. Aquí hay un fragmento de lo que espero:\n\n`performance_gain = (new_core_count * clock_speed) / current_arch` \n\n¿Qué opinan?', date: 'Hace 5 horas' }
  ]);
  const [newComment, setNewComment] = useState('');

  const updateMetaTags = (item: NewsItem) => {
    document.title = `${item.title} | SEOGrowthers`;
    let metaDescription = document.querySelector('meta[name="description"]');
    if (!metaDescription) {
      metaDescription = document.createElement('meta');
      metaDescription.setAttribute('name', 'description');
      document.head.appendChild(metaDescription);
    }
    metaDescription.setAttribute('content', item.excerpt);

    let metaKeywords = document.querySelector('meta[name="keywords"]');
    if (!metaKeywords) {
      metaKeywords = document.createElement('meta');
      metaKeywords.setAttribute('name', 'keywords');
      document.head.appendChild(metaKeywords);
    }
    const keywords = [
      item.category,
      'Tecnología',
      'Inteligencia Artificial',
      'Programación',
      'SEO Técnico',
      item.author,
      'Growth Hacking'
    ].join(', ');
    metaKeywords.setAttribute('content', keywords);
  };

  useEffect(() => {
    const savedUser = localStorage.getItem('user-session');
    if (savedUser) {
      setIsUserLoggedIn(true);
      setCurrentUser(JSON.parse(savedUser));
    }

    setIsLoading(true);
    setImageLoaded(false);
    const found = ALL_NEWS.find(n => n.id === id);

    const timer = setTimeout(() => {
      if (found) {
        setNews(found);
        updateMetaTags(found);
      }
      setIsLoading(false);
    }, 600);

    window.scrollTo(0, 0);

    const handleScroll = () => {
      setShowScrollTop(window.scrollY > 400);
    };

    window.addEventListener('scroll', handleScroll);
    return () => {
      window.removeEventListener('scroll', handleScroll);
      clearTimeout(timer);
      document.title = 'SEOGrowthers | Tech, AI & Growth';
    };
  }, [id]);

  const relatedNews = useMemo(() => {
    if (!news) return [];
    return ALL_NEWS
      .filter(n => n.category === news.category && n.id !== news.id)
      .slice(0, 3);
  }, [news]);

  const handleShare = async () => {
    if (!news) return;
    try {
      await navigator.clipboard.writeText(window.location.href);
      setShowCopied(true);
      setTimeout(() => setShowCopied(false), 2000);
    } catch (err) {
      console.error('Failed to copy:', err);
    }
  };

  const handleScrollToTop = () => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleAddComment = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newComment.trim() || !currentUser) return;
    const comment: Comment = {
      id: Date.now().toString(),
      user: currentUser.name,
      text: newComment,
      date: 'Justo ahora'
    };
    setComments([comment, ...comments]);
    setNewComment('');
  };

  if (isLoading) {
    return (
      <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-12 relative">
        <NewsDetailSkeleton />
      </div>
    );
  }

  if (!news) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-20 text-center">
        <h2 className="text-2xl font-bold text-white mb-4">Noticia no encontrada</h2>
        <Link to="/news" className="text-blue-400 hover:underline">Volver al archivo</Link>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-12 relative">
      <Link to="/news" className="inline-flex items-center text-sm text-slate-400 hover:text-blue-400 mb-8 transition-colors">
        <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-2" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
        </svg>
        Volver a noticias
      </Link>

      <header className="mb-8">
        <div className="flex items-center space-x-2 mb-4">
          <span className={`px-2 py-1 text-[10px] font-bold border rounded uppercase tracking-wider ${
            news.category === 'Shock' 
              ? 'bg-red-900/30 text-red-400 border-red-500/30' 
              : 'bg-blue-600/20 text-blue-400 border-blue-500/30'
          }`}>
            {news.category === 'Shock' ? 'SHOCK DIGITAL' : news.category}
          </span>
          <span className="text-slate-500 text-xs">•</span>
          <span className="text-slate-500 text-xs">{news.date}</span>
        </div>
        <h1 className="text-4xl md:text-5xl font-extrabold text-white leading-tight mb-6">
          {news.title}
        </h1>

        <div className="flex flex-wrap items-center justify-between gap-6 mb-8 pb-8 border-b border-[#30363d]">
          <div className="flex items-center space-x-3">
            <div className={`w-10 h-10 rounded-full border flex items-center justify-center font-bold shadow-sm ${
              news.category === 'Shock' 
                ? 'bg-red-600/20 border-red-500/30 text-red-400' 
                : 'bg-blue-600/20 border-blue-500/30 text-blue-400'
            }`}>
              {news.author.charAt(0)}
            </div>
            <div>
              <p className="text-sm font-semibold text-slate-200">{news.author}</p>
              <p className="text-xs text-slate-500">Editor en SEOGrowthers</p>
            </div>
          </div>

          <div className="flex items-center space-x-3">
            {showCopied && (
              <span className="text-[10px] font-mono text-green-400 animate-pulse">¡Enlace copiado!</span>
            )}
            <button 
              onClick={handleShare}
