import React, { useState, useEffect, useRef } from 'react';
import { Link } from 'react-router-dom';
import { NewsItem } from '../types';
import OptimizedImage from './OptimizedImage';

interface NewsCardProps {
  news: NewsItem;
}

const NewsCard: React.FC<NewsCardProps> = ({ news }) => {
  const [isVisible, setIsVisible] = useState(false);
  const cardRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
          observer.unobserve(entry.target);
        }
      },
      { threshold: 0.1 }
    );

    if (cardRef.current) {
      observer.observe(cardRef.current);
    }

    return () => {
      if (cardRef.current) {
        observer.unobserve(cardRef.current);
      }
    };
  }, []);

  const getCategoryColor = (category: string) => {
    switch (category) {
      case 'AI': return 'bg-purple-900/40 text-purple-300 border-purple-500/30';
      case 'Dev': return 'bg-blue-900/40 text-blue-300 border-blue-500/30';
      case 'Tech': return 'bg-green-900/40 text-green-300 border-green-500/30';
      case 'Shock': return 'bg-red-950/60 text-red-400 border-red-500/40 animate-pulse';
      default: return 'bg-slate-800 text-slate-300 border-slate-600/30';
    }
  };

  return (
    <Link to={`/news/${news.id}`} className={`group h-full block ${news.category === 'Shock' ? 'relative z-10' : ''}`}>
      <div 
        ref={cardRef}
        className={`bg-[#0d1117] border rounded-xl overflow-hidden hover:border-[#8b949e] transition-all duration-300 flex flex-col h-full shadow-lg hover:shadow-blue-500/10 active:scale-[0.98] ${
          news.category === 'Shock' ? 'border-red-900/30 ring-1 ring-red-500/10' : 'border-[#30363d]'
        }`}
      >
        {/* Image Container */}
        <div className="relative h-52 overflow-hidden border-b border-[#30363d] bg-slate-900">
          <OptimizedImage 
            src={news.imageUrl} 
            alt={news.title}
            containerClassName="w-full h-full"
            className={`w-full h-full object-cover group-hover:scale-105 group-hover:brightness-110 group-hover:contrast-[1.05] ${
              !isVisible ? 'scale-110 blur-sm' : ''
            }`}
          />

          {/* Subtle Glow Overlay */}
          <div className="absolute inset-0 z-10 bg-gradient-to-t from-[#0d1117]/80 via-transparent to-transparent opacity-60 group-hover:opacity-40 transition-opacity" />

          {/* Top Tag */}
          <div className="absolute top-4 left-4 z-20">
            <span className={`text-[10px] font-bold px-2.5 py-1 rounded-md border backdrop-blur-md uppercase tracking-wider shadow-sm flex items-center ${getCategoryColor(news.category)}`}>
              {news.category === 'Shock' && <span className="w-1.5 h-1.5 bg-red-500 rounded-full mr-1.5 animate-ping"></span>}
              {news.category === 'Shock' ? 'SHOCK DIGITAL' : news.category}
            </span>
          </div>

          {/* Hover Shine Effect */}
          <div className="absolute inset-0 z-15 opacity-0 group-hover:opacity-100 transition-opacity duration-700 pointer-events-none bg-gradient-to-r from-transparent via-white/10 to-transparent skew-x-[-20deg] transform -translate-x-full group-hover:translate-x-[150%] transition-transform duration-1000 ease-in-out" />
        </div>

        {/* Content Section */}
        <div className={`p-6 flex flex-col flex-grow bg-gradient-to-b ${news.category === 'Shock' ? 'from-red-950/10 to-[#0d1117]' : 'from-[#161b22] to-[#0d1117]'}`}>
          <h3 className={`text-lg font-bold transition-colors leading-snug mb-3 ${news.category === 'Shock' ? 'text-white group-hover:text-red-400' : 'text-slate-100 group-hover:text-blue-400'}`}>
            {news.title}
          </h3>
          <p className="text-sm text-slate-400 line-clamp-2 mb-5 flex-grow leading-relaxed">
            {news.excerpt}
          </p>

          <div className="flex items-center justify-between mt-auto pt-4 border-t border-[#30363d]/50">
            <div className="flex items-center space-x-2">
              <div className={`w-6 h-6 rounded-full border flex items-center justify-center text-[10px] font-bold ${news.category === 'Shock' ? 'bg-red-600/20 border-red-500/30 text-red-400' : 'bg-blue-600/20 border-blue-500/30 text-blue-400'}`}>
                {news.author.charAt(0)}
              </div>
              <span className="text-xs text-slate-300 font-medium">{news.author}</span>
            </div>
            <div className="flex items-center text-xs text-slate-500 font-mono">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3 mr-1 opacity-70" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
              </svg>
              {news.date}
            </div>
          </div>
        </div>
      </div>
    </Link>
  );
};

export default NewsCard;

import React from 'react';
import { ResourceItem } from '../types';
import OptimizedImage from './OptimizedImage';

interface ResourceCardProps {
  resource: ResourceItem;
}

const ResourceCard: React.FC<ResourceCardProps> = ({ resource }) => {
  const getDifficultyColor = (difficulty: string) => {
    switch (difficulty) {
      case 'Beginner': return 'bg-emerald-900/20 text-emerald-400 border-emerald-500/20';
      case 'Intermediate': return 'bg-amber-900/20 text-amber-400 border-amber-500/20';
      case 'Advanced': return 'bg-rose-900/20 text-rose-400 border-rose-500/20';
      default: return 'bg-slate-800 text-slate-300 border-slate-700';
    }
  };

  const getTypeIcon = (type: string) => {
    switch (type) {
      case 'Tutorial': return (
        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
        </svg>
      );
      case 'Guide': return (
        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
        </svg>
      );
      default: return (
        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
        </svg>
      );
    }
  };

  return (
    <div className="bg-[#161b22]/50 border border-[#30363d] rounded-2xl hover:border-blue-500/50 hover:bg-[#1c2128] transition-all duration-500 group flex flex-col h-full shadow-lg relative overflow-hidden cursor-pointer hover:shadow-blue-500/5">
      {/* Decorative top accent */}
      <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-blue-600 via-indigo-500 to-transparent opacity-0 group-hover:opacity-100 transition-opacity z-20"></div>

      {resource.imageUrl && (
        <div className="h-32 w-full border-b border-[#30363d]">
          <OptimizedImage 
            src={resource.imageUrl} 
            alt={resource.title}
            containerClassName="w-full h-full"
            className="w-full h-full object-cover group-hover:scale-110"
          />
        </div>
      )}

      <div className="p-8 flex flex-col flex-grow">
        <div className="flex justify-between items-start mb-8">
          <div className="p-3 bg-blue-500/10 border border-blue-500/20 rounded-xl text-blue-400 group-hover:bg-blue-500 group-hover:text-white transition-all duration-300">
            {getTypeIcon(resource.type)}
          </div>
          <span className={`text-[10px] font-mono font-bold uppercase tracking-widest border px-3 py-1 rounded-full ${getDifficultyColor(resource.difficulty)} shadow-sm`}>
            {resource.difficulty}
          </span>
        </div>

        <h4 className="text-2xl font-bold text-white mb-4 group-hover:text-blue-400 transition-colors leading-tight">
          {resource.title}
        </h4>
        <p className="text-slate-400 text-sm mb-8 line-clamp-3 leading-relaxed flex-grow">
          {resource.description}
        </p>

        <div className="mt-auto pt-6 border-t border-[#30363d]/50 flex flex-wrap gap-2">
          {resource.tags.map(tag => (
            <span key={tag} className="text-[10px] font-bold text-slate-500 bg-[#0d1117] px-2.5 py-1 rounded-md border border-[#30363d] transition-all group-hover:text-slate-300 group-hover:border-slate-700">
              #{tag}
            </span>
          ))}
        </div>

        <div className="mt-8 flex items-center text-blue-400 text-sm font-bold opacity-0 group-hover:opacity-100 transition-all transform translate-y-2 group-hover:translate-y-0">
          <span>Acceder al recurso</span>
          <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 ml-2" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 5l7 7m0 0l-7 7m7-7H3" />
          </svg>
        </div>
      </div>

      <a 
        href={resource.link} 
        target="_blank" 
        rel="noopener noreferrer" 
        className="absolute inset-0 z-10"
      >
        <span className="sr-only">Ver recurso: {resource.title}</span>
      </a>
    </div>
  );
};

export default ResourceCard;

import React, { useState, useEffect, useMemo } from 'react';
import { useParams, Link, useNavigate, useLocation } from 'react-router-dom';
import { ALL_NEWS } from '../constants/newsData';
import { NewsItem } from '../types';
import { marked } from 'marked';
import NewsCard from '../components/NewsCard';
import OptimizedImage from '../components/OptimizedImage';

interface Comment {
  id: string;
  user: string;
  text: string;
  date: string;
}

const NewsDetailSkeleton = () => (
  <div className="animate-pulse">
    <div className="h-4 w-32 bg-[#161b22] rounded mb-8" />
    <div className="flex space-x-2 mb-4">
      <div className="h-5 w-16 bg-[#161b22] rounded" />
      <div className="h-5 w-24 bg-[#161b22] rounded" />
    </div>
    <div className="h-12 w-full bg-[#161b22] rounded mb-6" />
    <div className="h-12 w-3/4 bg-[#161b22] rounded mb-8" />

    <div className="flex justify-between items-center pb-8 border-b border-slate-800 mb-8">
      <div className="flex space-x-3 items-center">
        <div className="w-10 h-10 rounded-full bg-[#161b22]" />
        <div className="space-y-2">
          <div className="h-4 w-24 bg-[#161b22] rounded" />
          <div className="h-3 w-32 bg-[#161b22] rounded" />
        </div>
      </div>
      <div className="h-10 w-28 bg-[#161b22] rounded-lg" />
    </div>

    <div className="h-96 w-full bg-[#161b22] rounded-2xl mb-12" />

    <div className="space-y-4">
      <div className="h-4 w-full bg-[#161b22] rounded" />
      <div className="h-4 w-full bg-[#161b22] rounded" />
      <div className="h-4 w-5/6 bg-[#161b22] rounded" />
      <div className="h-4 w-full bg-[#161b22] rounded" />
    </div>
  </div>
);

const NewsDetail: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const location = useLocation();
  const [news, setNews] = useState<NewsItem | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [showCopied, setShowCopied] = useState(false);
  const [showScrollTop, setShowScrollTop] = useState(false);
  const [isUserLoggedIn, setIsUserLoggedIn] = useState(false);
  const [currentUser, setCurrentUser] = useState<any>(null);

  const [comments, setComments] = useState<Comment[]>([
    { id: 'c1', user: 'TechEnthusiast', text: 'Excelente análisis. Esto cambia por completo las reglas del juego. **NVIDIA** está en otro nivel.', date: 'Hace 2 horas' },
    { id: 'c2', user: 'DevMaster', text: 'Me preocupa la eficiencia térmica de estos nuevos chips, pero el rendimiento es innegable. Aquí hay un fragmento de lo que espero:\n\n`performance_gain = (new_core_count * clock_speed) / current_arch` \n\n¿Qué opinan?', date: 'Hace 5 horas' }
  ]);
  const [newComment, setNewComment] = useState('');

  const updateMetaTags = (item: NewsItem) => {
    document.title = `${item.title} | SEOGrowthers`;
    let metaDescription = document.querySelector('meta[name="description"]');
    if (!metaDescription) {
      metaDescription = document.createElement('meta');
      metaDescription.setAttribute('name', 'description');
      document.head.appendChild(metaDescription);
    }
    metaDescription.setAttribute('content', item.excerpt);

    let metaKeywords = document.querySelector('meta[name="keywords"]');
    if (!metaKeywords) {
      metaKeywords = document.createElement('meta');
      metaKeywords.setAttribute('name', 'keywords');
      document.head.appendChild(metaKeywords);
    }
    const keywords = [
      item.category,
      'Tecnología',
      'Inteligencia Artificial',
      'Programación',
      'SEO Técnico',
      item.author,
      'Growth Hacking'
    ].join(', ');
    metaKeywords.setAttribute('content', keywords);
  };

  useEffect(() => {
    const savedUser = localStorage.getItem('user-session');
    if (savedUser) {
      setIsUserLoggedIn(true);
      setCurrentUser(JSON.parse(savedUser));
    }

    setIsLoading(true);
    const found = ALL_NEWS.find(n => n.id === id);

    const timer = setTimeout(() => {
      if (found) {
        setNews(found);
        updateMetaTags(found);
      }
      setIsLoading(false);
    }, 600);

    window.scrollTo(0, 0);

    const handleScroll = () => {
      setShowScrollTop(window.scrollY > 400);
    };

    window.addEventListener('scroll', handleScroll);
    return () => {
      window.removeEventListener('scroll', handleScroll);
      clearTimeout(timer);
      document.title = 'SEOGrowthers | Tech, AI & Growth';
    };
  }, [id]);

  const relatedNews = useMemo(() => {
    if (!news) return [];
    return ALL_NEWS
      .filter(n => n.category === news.category && n.id !== news.id)
      .slice(0, 3);
  }, [news]);

  const handleShare = async () => {
    if (!news) return;
    try {
      await navigator.clipboard.writeText(window.location.href);
      setShowCopied(true);
      setTimeout(() => setShowCopied(false), 2000);
    } catch (err) {
      console.error('Failed to copy:', err);
    }
  };

  const handleScrollToTop = () => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleAddComment = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newComment.trim() || !currentUser) return;
    const comment: Comment = {
      id: Date.now().toString(),
      user: currentUser.name,
      text: newComment,
      date: 'Justo ahora'
    };
    setComments([comment, ...comments]);
    setNewComment('');
  };

  if (isLoading) {
    return (
      <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-12 relative">
        <NewsDetailSkeleton />
      </div>
    );
  }

  if (!news) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-20 text-center">
        <h2 className="text-2xl font-bold text-white mb-4">Noticia no encontrada</h2>
        <Link to="/news" className="text-blue-400 hover:underline">Volver al archivo</Link>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-12 relative">
      <Link to="/news" className="inline-flex items-center text-sm text-slate-400 hover:text-blue-400 mb-8 transition-colors">
        <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-2" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
        </svg>
        Volver a noticias
      </Link>

      <header className="mb-8">
        <div className="flex items-center space-x-2 mb-4">
          <span className={`px-2 py-1 text-[10px] font-bold border rounded uppercase tracking-wider ${
            news.category === 'Shock' 
              ? 'bg-red-900/30 text-red-400 border-red-500/30' 
              : 'bg-blue-600/20 text-blue-400 border-blue-500/30'
          }`}>
            {news.category === 'Shock' ? 'SHOCK DIGITAL' : news.category}
          </span>
          <span className="text-slate-500 text-xs">•</span>
          <span className="text-slate-500 text-xs">{news.date}</span>
        </div>
        <h1 className="text-4xl md:text-5xl font-extrabold text-white leading-tight mb-6">
          {news.title}
        </h1>

        <div className="flex flex-wrap items-center justify-between gap-6 mb-8 pb-8 border-b border-[#30363d]">
          <div className="flex items-center space-x-3">
            <div className={`w-10 h-10 rounded-full border flex items-center justify-center font-bold shadow-sm ${
              news.category === 'Shock' 
                ? 'bg-red-600/20 border-red-500/30 text-red-400' 
                : 'bg-blue-600/20 border-blue-500/30 text-blue-400'
            }`}>
              {news.author.charAt(0)}
            </div>
            <div>
              <p className="text-sm font-semibold text-slate-200">{news.author}</p>
              <p className="text-xs text-slate-500">Editor en SEOGrowthers</p>
            </div>
          </div>

          <div className="flex items-center space-x-3">
            {showCopied && (
              <span className="text-[10px] font-mono text-green-400 animate-pulse">¡Enlace copiado!</span>
            )}
            <button 
              onClick={handleShare}
              className="inline-flex items-center space-x-2 px-4 py-2 rounded-lg bg-[#161b22] border border-[#30363d] text-slate-300 text-xs font-bold hover:bg-[#1f242c] hover:border-[#8b949e] hover:text-white transition-all shadow-sm"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z" />
              </svg>
              <span>Compartir</span>
            </button>
          </div>
        </div>
      </header>

      <div className="mb-12 rounded-2xl overflow-hidden border border-[#30363d] shadow-2xl relative min-h-[300px] bg-[#161b22]">
        <OptimizedImage 
          src={news.imageUrl} 
          alt={news.title}
          containerClassName="w-full h-full"
          className="w-full h-auto object-cover max-h-[500px]" 
        />
      </div>

      <article className="prose prose-invert max-w-none mb-16 px-0 md:px-2">
        <div className="relative mb-16 group">
          <div className="absolute -inset-y-4 -inset-x-6 bg-blue-500/5 rounded-2xl -z-10 transition-colors group-hover:bg-blue-500/[0.08]" />
          <p className="text-2xl md:text-3xl text-white leading-relaxed font-medium italic border-l-4 border-blue-500 pl-8 py-2">
            {news.excerpt}
          </p>
        </div>

        <div className="text-slate-100 text-xl md:text-2xl leading-[1.8] space-y-12 font-normal tracking-tight">
          {news.content?.split('\n\n').map((paragraph, idx) => (
            <p key={idx} className="transition-colors hover:text-white">{paragraph}</p>
          ))}
        </div>
      </article>

      {/* Related News Section */}
      {relatedNews.length > 0 && (
        <section className="py-12 border-t border-[#30363d]">
          <h3 className="text-2xl font-bold text-white mb-8">Noticias Relacionadas</h3>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            {relatedNews.map(item => (
              <div key={item.id} className="scale-90 origin-top-left -mr-[11%]">
                <NewsCard news={item} />
              </div>
            ))}
          </div>
        </section>
      )}

      {/* Comments Section */}
      <section className="pt-12 border-t border-[#30363d]">
        <div className="flex items-center justify-between mb-8">
          <h3 className="text-2xl font-bold text-white flex items-center">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 mr-3 text-blue-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" />
            </svg>
            Comentarios <span className="ml-2 px-2 py-0.5 bg-[#161b22] border border-[#30363d] rounded-full text-sm text-blue-400 font-mono">{comments.length}</span>
          </h3>
        </div>

        {/* Auth Restricted Form */}
        {isUserLoggedIn ? (
          <form onSubmit={handleAddComment} className="mb-12 animate-fade-in group">
            <div className="relative">
              <textarea
                value={newComment}
                onChange={(e) => setNewComment(e.target.value)}
                placeholder={`Como ${currentUser.name}, ¿qué opinas de esto?`}
                className="w-full bg-[#0d1117] border border-[#30363d] rounded-xl p-5 text-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-500/30 transition-all mb-4 h-32 text-sm leading-relaxed placeholder-slate-600 shadow-inner"
              />
              <div className="absolute bottom-6 right-3 text-[10px] font-mono text-slate-600 uppercase tracking-widest opacity-0 group-focus-within:opacity-100 transition-opacity">
                Presiona enter para publicar
              </div>
            </div>
            <button
              type="submit"
              disabled={!newComment.trim()}
              className="bg-blue-600 hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed text-white font-bold py-2.5 px-8 rounded-xl transition-all text-sm shadow-lg shadow-blue-500/20 active:scale-95"
            >
              Publicar comentario
            </button>
          </form>
        ) : (
          <div className="mb-12 p-10 bg-gradient-to-br from-[#161b22] to-[#0d1117] border border-dashed border-[#30363d] rounded-2xl text-center group">
            <div className="inline-flex items-center justify-center w-14 h-14 rounded-full bg-[#161b22] border border-[#30363d] mb-5 group-hover:scale-110 group-hover:border-blue-500/50 transition-all duration-300">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-7 w-7 text-slate-500 group-hover:text-blue-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
