import React, { useState, useEffect, useMemo } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import NewsCard from '../components/NewsCard';
import { ALL_NEWS } from '../constants/newsData';

const NewsSkeleton = () => (
  <div className="bg-[#0d1117] border border-[#30363d] rounded-xl overflow-hidden h-full flex flex-col animate-pulse">
    <div className="h-52 bg-[#161b22]" />
    <div className="p-6 space-y-4 flex-grow">
      <div className="h-4 w-1/4 bg-[#161b22] rounded" />
      <div className="h-6 w-3/4 bg-[#161b22] rounded" />
      <div className="space-y-2">
        <div className="h-3 w-full bg-[#161b22] rounded" />
        <div className="h-3 w-5/6 bg-[#161b22] rounded" />
      </div>
    </div>
  </div>
);

const News: React.FC = () => {
  const { categorySlug } = useParams<{ categorySlug?: string }>();
  const navigate = useNavigate();
  const [isLoading, setIsLoading] = useState(true);

  // Mapeo de slugs a categorías internas
  const slugToCategory: Record<string, string> = {
    'shock-digital': 'Shock',
    'ai': 'AI',
    'dev': 'Dev',
    'tech': 'Tech',
    'hardware': 'Hardware'
  };

  const categoryToSlug = Object.fromEntries(
    Object.entries(slugToCategory).map(([slug, cat]) => [cat, slug])
  );

  const currentCategory = categorySlug ? slugToCategory[categorySlug] : 'All';

  useEffect(() => {
    setIsLoading(true);
    const timer = setTimeout(() => setIsLoading(false), 800);
    return () => clearTimeout(timer);
  }, [categorySlug]);

  const filteredNews = useMemo(() => {
    return currentCategory === 'All' 
      ? ALL_NEWS 
      : ALL_NEWS.filter(n => n.category === currentCategory);
  }, [currentCategory]);

  // Siempre obtener las 2 últimas noticias de Shock para el bloque especial
  const latestShockNews = useMemo(() => {
    return ALL_NEWS
      .filter(n => n.category === 'Shock')
      .slice(0, 2);
  }, []);

  const categories = [
    { id: 'All', label: 'Todos', slug: null },
    { id: 'Shock', label: 'Shock Digital', slug: 'shock-digital' },
    { id: 'AI', label: 'AI', slug: 'ai' },
    { id: 'Dev', label: 'Dev', slug: 'dev' },
    { id: 'Tech', label: 'Tech', slug: 'tech' },
    { id: 'Hardware', label: 'Hardware', slug: 'hardware' }
  ];

  const handleCategoryClick = (slug: string | null) => {
    if (slug) {
      navigate(`/news/category/${slug}`);
    } else {
      navigate('/news');
    }
  };

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
      <div className="mb-12">
        <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 mb-8">
          <div>
            <h1 className="text-4xl font-bold text-white mb-4">Archivo de Noticias</h1>
            <p className="text-slate-400 max-w-2xl">Explora nuestra colección completa de artículos sobre IA, desarrollo y las noticias más impactantes del Shock Digital.</p>
          </div>

          <div className="flex flex-wrap gap-2">
            {categories.map(cat => (
              <button
                key={cat.id}
                onClick={() => handleCategoryClick(cat.slug)}
                className={`px-4 py-1.5 rounded-full text-sm font-medium transition-all border ${
                  currentCategory === cat.id 
                    ? cat.id === 'Shock' ? 'bg-red-600 border-red-500 text-white' : 'bg-blue-600 border-blue-500 text-white'
                    : 'bg-[#161b22] border-[#30363d] text-slate-400 hover:border-[#8b949e]'
                }`}
              >
                {cat.label}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* BLOQUE ESPECIAL: ALERTA SHOCK DIGITAL */}
      {/* Se muestra siempre en 'Todos' o en la categoría 'Shock' */}
      {(currentCategory === 'All' || currentCategory === 'Shock') && latestShockNews.length > 0 && !isLoading && (
        <section className="mb-16 relative">
          <div className="border-2 border-dashed border-red-500/40 rounded-3xl p-8 pt-10 relative">
            {/* Etiqueta del bloque */}
            <div className="absolute -top-4 left-8 px-4 py-1 bg-[#0d1117] flex items-center space-x-2">
              <span className="flex h-2 w-2 relative">
                <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span>
                <span className="relative inline-flex rounded-full h-2 w-2 bg-red-500"></span>
              </span>
              <h2 className="text-sm font-bold text-red-500 uppercase tracking-[0.2em]">
                ALERTA: SHOCK DIGITAL
              </h2>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              {latestShockNews.map(news => (
                <div key={news.id} className="transform hover:scale-[1.01] transition-transform">
                  <NewsCard news={news} />
                </div>
              ))}
            </div>
          </div>
        </section>
      )}

      {/* Rejilla Principal de Noticias */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
        {isLoading ? (
          Array.from({ length: 6 }).map((_, i) => <NewsSkeleton key={i} />)
        ) : (
          filteredNews
            .filter(n => currentCategory === 'Shock' || n.category !== 'Shock')
            .map(news => (
              <NewsCard key={news.id} news={news} />
            ))
        )}
      </div>

      {!isLoading && filteredNews.length === 0 && (
        <div className="text-center py-20">
          <p className="text-slate-500 italic">No hay noticias en esta categoría por ahora.</p>
        </div>
      )}
    </div>
  );
};

