             <div className="w-2 h-2 bg-blue-500 rounded-sm rotate-45 animate-pulse"></div>
             <h2 className="text-xs font-black text-slate-400 uppercase tracking-[0.3em] group-hover:text-blue-400 transition-colors">BLOQUE: ARTÍCULOS PUBLICADOS</h2>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-x-8 gap-y-10">
            {isLoading ? (
              Array.from({ length: 6 }).map((_, i) => <NewsSkeleton key={i} />)
            ) : (
              paginatedNews.map(news => (
                <div key={news.id} className="h-full transform hover:translate-y-[-4px] transition-transform duration-300">
                  <NewsCard news={news} />
                </div>
              ))
            )}
          </div>

          {!isLoading && filteredNews.length === 0 && (
            <div className="text-center py-24">
              <p className="text-slate-500 text-lg font-medium italic">No se encontraron artículos en esta sección.</p>
              <button onClick={() => navigate('/news')} className="mt-6 text-blue-500 hover:text-blue-400 font-bold transition-colors">Volver al archivo completo</button>
            </div>
          )}
        </div>
      </section>

      {/* PAGINACIÓN */}
      {!isLoading && totalPages > 1 && (
        <div className="flex flex-col items-center justify-center space-y-6 mt-16 pt-8 border-t border-[#30363d]">
          <div className="flex items-center space-x-3">
            <button
              onClick={() => handlePageChange(Math.max(1, currentPage - 1))}
              disabled={currentPage === 1}
              className="px-6 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all bg-[#161b22] border border-[#30363d] text-slate-500 hover:text-white hover:border-slate-500 disabled:opacity-20 disabled:cursor-not-allowed"
            >
              Anterior
            </button>

            <div className="flex space-x-2">
              {Array.from({ length: totalPages }, (_, i) => i + 1).map(page => (
                <button
                  key={page}
                  onClick={() => handlePageChange(page)}
                  className={`w-12 h-12 rounded-xl text-sm font-black transition-all border ${
                    currentPage === page
                      ? 'bg-blue-600 text-white border-blue-400 shadow-xl shadow-blue-500/20 scale-110'
                      : 'bg-[#0d1117] text-slate-500 border border-[#30363d] hover:border-slate-500 hover:text-slate-200'
                  }`}
                >
                  {page}
                </button>
              ))}
            </div>

            <button
              onClick={() => handlePageChange(Math.min(totalPages, currentPage + 1))}
              disabled={currentPage === totalPages}
              className="px-6 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all bg-[#161b22] border border-[#30363d] text-slate-500 hover:text-white hover:border-slate-500 disabled:opacity-20 disabled:cursor-not-allowed"
            >
              Siguiente
            </button>
          </div>
          <div className="px-4 py-1 bg-[#161b22] border border-[#30363d] rounded-full text-[10px] text-slate-500 font-mono uppercase tracking-[0.3em]">
            Página {currentPage} / {totalPages}
          </div>
        </div>
      )}
    </div>
  );
};

