import React, { useState, useEffect, useRef } from 'react';
import { Link } from 'react-router-dom';
import { NewsItem } from '../types';
import OptimizedImage from './OptimizedImage';

interface NewsCardProps {
  news: NewsItem;
}

const NewsCard: React.FC<NewsCardProps> = ({ news }) => {
  const [isVisible, setIsVisible] = useState(false);
  const cardRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
          observer.unobserve(entry.target);
        }
      },
      { threshold: 0.1 }
    );

    if (cardRef.current) {
      observer.observe(cardRef.current);
    }

    return () => {
      if (cardRef.current) {
        observer.unobserve(cardRef.current);
      }
    };
  }, []);

  const getCategoryColor = (category: string) => {
    switch (category) {
      case 'AI': return 'bg-purple-900/40 text-purple-300 border-purple-500/30';
      case 'Dev': return 'bg-blue-900/40 text-blue-300 border-blue-500/30';
      case 'Tech': return 'bg-green-900/40 text-green-300 border-green-500/30';
      case 'Shock': return 'bg-red-950/60 text-red-400 border-red-500/40 animate-pulse';
      default: return 'bg-slate-800 text-slate-300 border-slate-600/30';
    }
  };

  return (
    <Link to={`/news/${news.id}`} className={`group h-full block ${news.category === 'Shock' ? 'relative z-10' : ''}`}>
      <div 
        ref={cardRef}
        className={`bg-[#0d1117] border rounded-xl overflow-hidden hover:border-[#8b949e] transition-all duration-500 flex flex-col h-full shadow-lg hover:shadow-blue-500/10 hover:scale-[1.02] active:scale-[0.98] ${
          news.category === 'Shock' ? 'border-red-900/30 ring-1 ring-red-500/10' : 'border-[#30363d]'
        }`}
      >
        {/* Image Container */}
        <div className="relative h-52 overflow-hidden border-b border-[#30363d] bg-[#161b22]">
          {/* Shimmer Placeholder while not visible or loading */}
          {!isVisible && (
            <div className="absolute inset-0 z-30 shimmer opacity-60" />
          )}

          <OptimizedImage 
            src={news.imageUrl} 
            alt={news.title}
            containerClassName="w-full h-full"
            className={`w-full h-full object-cover transition-all duration-700 ease-out group-hover:scale-110 group-hover:brightness-110 group-hover:contrast-[1.05] ${
              !isVisible ? 'scale-110 blur-sm opacity-0' : 'scale-100 blur-0 opacity-100'
            }`}
          />

          {/* Subtle Glow Overlay */}
          <div className="absolute inset-0 z-10 bg-gradient-to-t from-[#0d1117]/90 via-transparent to-transparent opacity-60 group-hover:opacity-30 transition-opacity duration-500" />

          {/* Top Tag */}
          <div className="absolute top-4 left-4 z-20">
            <span className={`text-[10px] font-bold px-2.5 py-1 rounded-md border backdrop-blur-md uppercase tracking-wider shadow-sm flex items-center transition-all group-hover:scale-105 ${getCategoryColor(news.category)}`}>
              {news.category === 'Shock' && <span className="w-1.5 h-1.5 bg-red-500 rounded-full mr-1.5 animate-ping"></span>}
              {news.category === 'Shock' ? 'SHOCK DIGITAL' : news.category}
            </span>
          </div>

          {/* Hover Shine Effect */}
          <div className="absolute inset-0 z-15 opacity-0 group-hover:opacity-100 transition-opacity duration-1000 pointer-events-none bg-gradient-to-r from-transparent via-white/10 to-transparent skew-x-[-20deg] transform -translate-x-full group-hover:translate-x-[150%] transition-transform ease-in-out" />
        </div>

        {/* Content Section */}
        <div className={`p-6 flex flex-col flex-grow transition-colors duration-500 bg-gradient-to-b ${news.category === 'Shock' ? 'from-red-950/10 to-[#0d1117] group-hover:from-red-950/20' : 'from-[#161b22] to-[#0d1117] group-hover:from-[#1c2128]'}`}>
          <h3 className={`text-lg font-bold transition-colors duration-300 leading-snug mb-3 ${news.category === 'Shock' ? 'text-white group-hover:text-red-400' : 'text-slate-100 group-hover:text-blue-400'}`}>
            {news.title}
          </h3>
          <p className="text-sm text-slate-400 line-clamp-2 mb-5 flex-grow leading-relaxed group-hover:text-slate-300 transition-colors">
            {news.excerpt}
          </p>

          <div className="flex items-center justify-between mt-auto pt-4 border-t border-[#30363d]/50">
            <div className="flex items-center space-x-2">
              <div className={`w-6 h-6 rounded-full border flex items-center justify-center text-[10px] font-bold transition-transform group-hover:scale-110 ${news.category === 'Shock' ? 'bg-red-600/20 border-red-500/30 text-red-400' : 'bg-blue-600/20 border-blue-500/30 text-blue-400'}`}>
                {news.author.charAt(0)}
              </div>
              <span className="text-xs text-slate-300 font-medium group-hover:text-white transition-colors">{news.author}</span>
