        <div className="text-slate-300 text-lg md:text-xl leading-[1.75] space-y-8 font-normal tracking-normal text-pretty">
          {news.content?.split('\n\n').map((paragraph, idx) => (
            <p key={idx} className="transition-colors hover:text-white duration-300">{paragraph}</p>
          ))}
        </div>
      </article>

      {/* Related News Section - REDESIGNED */}
      {relatedNews.length > 0 && (
        <section className="py-16 border-t border-[#30363d]">
          <div className="flex items-center space-x-3 mb-10">
            <div className="w-1.5 h-6 bg-blue-600 rounded-full"></div>
            <h3 className="text-2xl font-bold text-white tracking-tight">Noticias Relacionadas</h3>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-8">
            {relatedNews.map((item, idx) => (
              <div 
                key={item.id} 
                className="animate-fade-in-up" 
                style={{ animationDelay: `${idx * 150}ms` }}
              >
                <NewsCard news={item} />
              </div>
            ))}
          </div>
        </section>
      )}

      {/* Comments Section */}
      <section className="pt-12 border-t border-[#30363d]">
        <div className="flex items-center justify-between mb-8">
          <h3 className="text-2xl font-bold text-white flex items-center">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 mr-3 text-blue-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" />
            </svg>
            Comentarios <span className="ml-2 px-2 py-0.5 bg-[#161b22] border border-[#30363d] rounded-full text-sm text-blue-400 font-mono">{comments.length}</span>
          </h3>
        </div>

        {/* Auth Restricted Form */}
        {isUserLoggedIn ? (
          <form onSubmit={handleAddComment} className="mb-12 animate-fade-in group">
            <div className="relative">
              <textarea
                value={newComment}
                onChange={(e) => setNewComment(e.target.value)}
                placeholder={`Como ${currentUser.name}, ¿qué opinas de esto?`}
                className="w-full bg-[#0d1117] border border-[#30363d] rounded-xl p-5 text-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-500/30 transition-all mb-4 h-32 text-sm leading-relaxed placeholder-slate-600 shadow-inner"
              />
              <div className="absolute bottom-6 right-3 text-[10px] font-mono text-slate-600 uppercase tracking-widest opacity-0 group-focus-within:opacity-100 transition-opacity">
                Presiona enter para publicar
              </div>
            </div>
            <button
              type="submit"
              disabled={!newComment.trim()}
              className="bg-blue-600 hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed text-white font-bold py-2.5 px-8 rounded-xl transition-all text-sm shadow-lg shadow-blue-500/20 active:scale-95"
            >
              Publicar comentario
            </button>
          </form>
        ) : (
          <div className="mb-12 p-10 bg-gradient-to-br from-[#161b22] to-[#0d1117] border border-dashed border-[#30363d] rounded-2xl text-center group">
            <div className="inline-flex items-center justify-center w-14 h-14 rounded-full bg-[#161b22] border border-[#30363d] mb-5 group-hover:scale-110 group-hover:border-blue-500/50 transition-all duration-300">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-7 w-7 text-slate-500 group-hover:text-blue-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
              </svg>
            </div>
            <h4 className="text-white text-lg font-bold mb-2">Únete a la discusión técnica</h4>
            <p className="text-sm text-slate-400 mb-8 max-w-sm mx-auto leading-relaxed">
              Solo los miembros de SEOGrowthers pueden publicar comentarios. Regístrate para compartir tus insights con la comunidad.
            </p>
            <Link 
              to="/login" 
              state={{ from: location }}
              className="inline-block bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 px-8 rounded-xl transition-all shadow-lg shadow-blue-500/10"
            >
              Iniciar sesión / Registro
            </Link>
          </div>
        )}

        <div className="space-y-6">
          {comments.map((comment, idx) => (
            <div 
              key={comment.id} 
              className="flex space-x-4 animate-fade-in-up group"
              style={{ animationDelay: `${idx * 100}ms` }}
            >
              <div className="flex-shrink-0">
                <div className="w-12 h-12 rounded-xl bg-gradient-to-br from-[#161b22] to-[#0d1117] border border-[#30363d] flex items-center justify-center text-sm font-bold text-blue-400 shadow-md group-hover:border-blue-500/30 transition-colors">
                  {comment.user.charAt(0)}
                </div>
              </div>
              <div className="flex-grow">
                <div className="flex items-center space-x-2 mb-1.5">
                  <span className="text-sm font-bold text-slate-200 group-hover:text-blue-400 transition-colors cursor-pointer">{comment.user}</span>
                  <span className="text-[10px] text-slate-500 font-mono tracking-tighter uppercase">{comment.date}</span>
                </div>
                <div 
                  className="comment-content prose prose-sm prose-invert max-w-none text-slate-300 bg-[#161b22]/50 border border-[#30363d] rounded-2xl rounded-tl-none p-5 leading-relaxed shadow-sm group-hover:bg-[#161b22] group-hover:border-[#8b949e]/30 transition-all"
                  dangerouslySetInnerHTML={{ __html: marked.parse(comment.text) }}
                />

                <div className="flex items-center space-x-4 mt-2 ml-1">
                  <button className="text-[10px] font-bold text-slate-500 hover:text-blue-400 transition-colors flex items-center uppercase tracking-widest">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3 mr-1" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 10h4.757c1.246 0 2.256 1.01 2.256 2.256 0 1.246-1.01 2.256-2.256 2.256H19l-4 4V10z" />
                    </svg>
                    Responder
                  </button>
                  <button className="text-[10px] font-bold text-slate-500 hover:text-red-400 transition-colors flex items-center uppercase tracking-widest">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3 mr-1" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z" />
                    </svg>
                    Útil
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      </section>

      <button
        onClick={handleScrollToTop}
        className={`fixed bottom-8 right-8 z-50 p-3.5 rounded-2xl bg-[#161b22] border border-[#30363d] text-slate-400 hover:text-blue-400 hover:border-blue-500/50 hover:bg-[#1f242c] transition-all duration-300 shadow-2xl ${
          showScrollTop ? 'translate-y-0 opacity-100 scale-100' : 'translate-y-12 opacity-0 scale-75 pointer-events-none'
        }`}
      >
        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 10l7-7m0 0l7 7m-7-7v18" />
        </svg>
      </button>
    </div>
  );
};

