  const handleShare = async () => {
    if (!news) return;
    const shareData = {
      title: news.title,
      text: news.excerpt,
      url: window.location.href,
    };

    if (navigator.share && navigator.canShare && navigator.canShare(shareData)) {
      try {
        await navigator.share(shareData);
      } catch (err) {
        if (err instanceof Error && err.name !== 'AbortError') {
