import React, { useState, useEffect } from 'react';
import { Link, NavLink, useNavigate, useSearchParams } from 'react-router-dom';
import Logo from './Logo';
import { useTheme } from '../contexts/ThemeContext';

const Navbar: React.FC = () => {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const { isDarkMode, toggleTheme } = useTheme();
  const [searchTerm, setSearchTerm] = useState(searchParams.get('q') || '');

  // Update search term state if query param changes externally
  useEffect(() => {
    setSearchTerm(searchParams.get('q') || '');
  }, [searchParams]);

  const handleSearch = () => {
    if (searchTerm.trim()) {
      navigate(`/news?q=${encodeURIComponent(searchTerm.trim())}`);
    } else {
      navigate('/news');
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      handleSearch();
    }
  };

  const navLinks = [
    { name: 'Inicio', path: '/' },
    { name: 'Noticias', path: '/news' },
    { name: 'Recursos', path: '/resources' },
    { name: 'Proyectos', path: '/showcase' },
    { name: 'Growth IA', path: '/ask-ai' },
  ];

  return (
    <nav className="fixed top-0 w-full z-50 glass">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between h-16 items-center">
          <div className="flex items-center space-x-8">
            <Link to="/" className="flex items-center space-x-3 group hover-vibrate">
              <Logo size="md" />
              <span className="text-xl font-bold text-slate-100 tracking-tight transition-colors">SEOGrowthers</span>
            </Link>

            <div className="hidden md:flex space-x-8">
              {navLinks.map((link) => (
                <NavLink
                  key={link.path}
                  to={link.path}
                  className={({ isActive }) => `
                    text-sm transition-all duration-200 hover:text-blue-400 relative py-1 hover-vibrate
                    ${isActive ? 'text-white font-bold tracking-tight' : 'text-slate-400 font-medium'}
                  `}
                >
                  {({ isActive }) => (
                    <>
                      {link.name}
                      {isActive && (
                        <span className="absolute -bottom-1.5 left-0 w-full h-0.5 bg-blue-500 rounded-full animate-fade-in shadow-[0_0_8px_rgba(59,130,246,0.5)]" />
                      )}
                    </>
                  )}
                </NavLink>
              ))}
            </div>
          </div>

          <div className="flex items-center space-x-4">
            <div className="relative hidden lg:block">
              <input 
                type="text" 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                onKeyDown={handleKeyDown}
                placeholder="Buscar tácticas SEO..." 
                className="bg-[#010409] border border-[#30363d] rounded-md py-1.5 px-3 pr-10 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/50 w-64 transition-all placeholder-slate-500"
              />
              <button 
                onClick={handleSearch}
                className="absolute right-8 top-1/2 -translate-y-1/2 text-slate-500 hover:text-blue-500 transition-colors p-1"
                aria-label="Buscar"
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                </svg>
              </button>
            </div>

            <button 
              onClick={toggleTheme}
              className="p-2 rounded-lg hover:bg-slate-500/10 transition-colors text-slate-400 hover:text-blue-500"
              title={isDarkMode ? "Cambiar a modo claro" : "Cambiar a modo oscuro"}
            >
              {isDarkMode ? (
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364-6.364l-.707.707M6.343 17.657l-.707.707M17.657 17.657l-.707-.707M6.343 6.343l-.707-.707M12 5a7 7 0 100 14 7 7 0 000-14z" />
                </svg>
              ) : (
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z" />
                </svg>
              )}
            </button>

            <Link 
              to="/showcase"
              className="bg-blue-600 hover:bg-blue-700 text-white text-xs font-bold py-2.5 px-5 rounded-lg transition-all shadow-md shadow-blue-500/20 hover-vibrate animate-pulse"
            >
              Showcase & Contacto
            </Link>
          </div>
        </div>
      </div>
    </nav>
  );
};

