                      <option>SEO Técnico / Auditoría</option>
                      <option>Desarrollo IA / LLMs</option>
                      <option>Automatización de Contenido</option>
                      <option>SaaS / Web App</option>
                      <option>Otros</option>
                    </select>
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-mono text-slate-500 uppercase">Mensaje / Desafío</label>
                    <textarea 
                      required rows={4} value={formData.message} onChange={e => setFormData({...formData, message: e.target.value})}
                      placeholder="Cuéntanos brevemente qué necesitas..."
                      className="w-full bg-[#0d1117] border border-[#30363d] rounded-xl p-3 text-slate-200 focus:outline-none focus:ring-1 focus:ring-blue-500 text-sm resize-none"
                    />
                  </div>
                  <button 
                    type="submit" 
                    disabled={isSubmitting}
                    onClick={handleRipple}
                    className="ripple-container w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-4 rounded-xl shadow-lg transition-all disabled:opacity-50"
                  >
                    {isSubmitting ? 'Iniciando transmisión...' : 'Enviar Solicitud'}
                  </button>
                </form>
              )}
            </div>
          </div>
        </div>
      </section>
    </div>
  );
};

export default Showcase;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Link } from 'react-router-dom';
import { NewsItem } from '../types';
import OptimizedImage from './OptimizedImage';

interface NewsCardProps {
  news: NewsItem;
}

const NewsCard: React.FC<NewsCardProps> = ({ news }) => {
  const [isVisible, setIsVisible] = useState(false);
  const [showShareMenu, setShowShareMenu] = useState(false);
  const [showCopied, setShowCopied] = useState(false);
  const cardRef = useRef<HTMLDivElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);

  // Determine if the news item is recent (last 3 days)
  const isRecent = useMemo(() => {
    if (news.date === 'Hoy' || news.date === 'Ayer') return true;

    const newsDate = new Date(news.date);
    if (!isNaN(newsDate.getTime())) {
      const diffTime = Math.abs(new Date().getTime() - newsDate.getTime());
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      return diffDays <= 3;
    }
    return false;
  }, [news.date]);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
          observer.unobserve(entry.target);
        }
      },
      { 
        threshold: 0.15,
        rootMargin: '50px' // Start loading slightly before it enters
      }
    );

    if (cardRef.current) {
      observer.observe(cardRef.current);
    }

    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setShowShareMenu(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);

    return () => {
      if (cardRef.current) {
        observer.unobserve(cardRef.current);
      }
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  const getCategoryColor = (category: string) => {
    switch (category) {
      case 'AI': return 'bg-purple-900/40 text-purple-300 border-purple-500/30 hover:bg-purple-800/60 hover:text-purple-100 hover:border-purple-400/50';
      case 'Dev': return 'bg-blue-900/40 text-blue-300 border-blue-500/30 hover:bg-blue-800/60 hover:text-blue-100 hover:border-blue-400/50';
      case 'Tech': return 'bg-green-900/40 text-green-300 border-green-500/30 hover:bg-green-800/60 hover:text-green-100 hover:border-green-400/50';
      case 'Shock': return 'bg-red-950/60 text-red-400 border-red-500/40 animate-pulse hover:bg-red-900 hover:text-white hover:border-red-400';
      default: return 'bg-slate-800 text-slate-300 border-slate-600/30 hover:bg-slate-700 hover:text-white';
    }
  };

  const handleShareClick = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setShowShareMenu(!showShareMenu);
  };

  const handleShareAction = (e: React.MouseEvent, platform: 'twitter' | 'linkedin' | 'copy') => {
    e.preventDefault();
    e.stopPropagation();

    const url = `${window.location.origin}/#/news/${news.id}`;
    const title = news.title;

    if (platform === 'twitter') {
      window.open(`https://twitter.com/intent/tweet?text=${encodeURIComponent(title)}&url=${encodeURIComponent(url)}`, '_blank');
    } else if (platform === 'linkedin') {
      window.open(`https://www.linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(url)}`, '_blank');
    } else if (platform === 'copy') {
      navigator.clipboard.writeText(url);
      setShowCopied(true);
      setTimeout(() => setShowCopied(false), 2000);
    }

    setShowShareMenu(false);
  };

  return (
    <Link to={`/news/${news.id}`} className={`group h-full block ${news.category === 'Shock' ? 'relative z-10' : ''}`}>
      <div 
        ref={cardRef}
        className={`bg-[#0d1117] border rounded-xl overflow-hidden transition-all duration-500 ease-[cubic-bezier(0.34,1.56,0.64,1)] flex flex-col h-full shadow-lg group-hover:shadow-blue-500/20 group-hover:scale-[1.03] group-hover:-translate-y-1 active:scale-[0.98] ${
          news.category === 'Shock' ? 'border-red-900/30 ring-1 ring-red-500/10 group-hover:border-red-500/50 group-hover:shadow-red-500/20' : 'border-[#30363d] group-hover:border-[#8b949e]'
        }`}
      >
        {/* Image Container */}
        <div className="border-b border-[#30363d] bg-[#161b22] relative overflow-hidden h-52">
          {/* Shimmer Overlay when not visible */}
          {!isVisible && (
            <div className="absolute inset-0 z-30 shimmer opacity-60" />
          )}

          <div className={`w-full h-full transition-all duration-1000 ${isVisible ? 'opacity-100' : 'opacity-0'}`}>
            <OptimizedImage 
              src={news.imageUrl} 
              alt={news.title}
              containerClassName={`w-full h-full transition-all duration-700 ${
                news.category === 'Shock' 
                  ? 'border-4 border-red-600/60 shadow-[inset_0_0_20px_rgba(220,38,38,0.2)]' 
                  : ''
              }`}
              className={`w-full h-full object-cover transition-all duration-700 ease-out group-hover:scale-110 group-hover:brightness-110 ${
                !isVisible ? 'scale-110 blur-sm' : 'scale-100 blur-0'
              } ${news.category === 'Shock' ? 'animate-[pulse_4s_ease-in-out_infinite]' : ''}`}
            />
          </div>

          <div className="absolute inset-0 z-10 bg-gradient-to-t from-[#0d1117]/90 via-transparent to-transparent opacity-60 group-hover:opacity-30 transition-opacity duration-500" />

          <div className="absolute top-4 left-4 z-20">
            <span className={`text-[10px] font-bold px-2.5 py-1 rounded-md border backdrop-blur-md uppercase tracking-wider shadow-sm flex items-center transition-all duration-300 group-hover:scale-105 select-none ${getCategoryColor(news.category)}`}>
              {news.category === 'Shock' && <span className="w-1.5 h-1.5 bg-red-500 rounded-full mr-1.5 animate-ping"></span>}
              {news.category === 'Shock' ? 'SHOCK DIGITAL' : news.category}
            </span>
          </div>

          {isRecent && (
            <div className="absolute top-4 right-4 z-20 animate-fade-in">
              <span className="text-[10px] font-black px-3 py-1 bg-blue-600 text-white rounded-md border border-blue-400/50 uppercase tracking-widest shadow-[0_0_15px_rgba(37,99,235,0.4)]">
                Nuevo
              </span>
            </div>
          )}
        </div>

        {/* Content Section */}
        <div className={`p-6 flex flex-col flex-grow transition-colors duration-500 bg-gradient-to-b ${news.category === 'Shock' ? 'from-red-950/10 to-[#0d1117] group-hover:from-red-950/20' : 'from-[#161b22] to-[#0d1117] group-hover:from-[#1c2128]'}`}>
          <h3 className={`text-lg font-bold leading-snug mb-3 transition-all duration-500 ease-[cubic-bezier(0.23,1,0.32,1)] group-hover:translate-x-1 ${
            news.category === 'Shock' 
              ? 'text-white group-hover:text-red-400 group-hover:drop-shadow-[0_0_15px_rgba(239,68,68,0.4)]' 
              : 'text-slate-100 group-hover:text-blue-400 group-hover:drop-shadow-[0_0_15px_rgba(59,130,246,0.4)]'
          }`}>
            {news.title}
          </h3>
          <p className="text-sm text-slate-400 line-clamp-2 mb-5 flex-grow leading-relaxed group-hover:text-slate-300 transition-colors">
            {news.excerpt}
          </p>

          <div className="flex items-center justify-between mt-auto pt-4 border-t border-[#30363d]/50 relative">
            <div className="flex items-center space-x-2">
              <div className={`w-6 h-6 rounded-full border flex items-center justify-center text-[10px] font-bold transition-transform group-hover:scale-110 ${news.category === 'Shock' ? 'bg-red-600/20 border-red-500/30 text-red-400' : 'bg-blue-600/20 border-blue-500/30 text-blue-400'}`}>
                {news.author.charAt(0)}
              </div>
              <span className="text-xs text-slate-300 font-medium group-hover:text-white transition-colors">{news.author}</span>
            </div>

            <div className="flex items-center space-x-3">
              {showCopied && (
                <span className="text-[10px] font-mono text-emerald-400 animate-fade-in uppercase tracking-tighter">Copiado</span>
              )}

              <div className="relative" ref={menuRef}>
                <button 
                  onClick={handleShareClick}
                  className="p-1.5 rounded-lg bg-[#161b22] border border-[#30363d] text-slate-400 hover:text-blue-400 hover:border-blue-500/50 transition-all active:scale-90"
                  aria-label="Compartir"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z" />
                  </svg>
                </button>

                {showShareMenu && (
                  <div className="absolute bottom-full right-0 mb-2 w-40 bg-[#161b22]/95 backdrop-blur-md border border-[#30363d] rounded-xl shadow-2xl py-2 z-50 animate-fade-in-up">
                    <button 
                      onClick={(e) => handleShareAction(e, 'twitter')}
                      className="w-full text-left px-4 py-2 text-xs text-slate-300 hover:bg-blue-500/10 hover:text-white flex items-center space-x-2 transition-colors"
                    >
                      <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 24 24"><path d="M18.244 2.25h3.308l-7.227 8.26 8.502 11.24H16.17l-5.214-6.817L4.99 21.75H1.68l7.73-8.835L1.254 2.25H8.08l4.713 6.231zm-1.161 17.52h1.833L7.084 4.126H5.117z"/></svg>
                      <span>Compartir en X</span>
                    </button>
                    <button 
                      onClick={(e) => handleShareAction(e, 'linkedin')}
                      className="w-full text-left px-4 py-2 text-xs text-slate-300 hover:bg-blue-500/10 hover:text-white flex items-center space-x-2 transition-colors"
                    >
                      <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 24 24"><path d="M20.447 20.452h-3.554v-5.569c0-1.328-.027-3.037-1.852-3.037-1.853 0-2.136 1.445-2.136 2.939v5.667H9.351V9h3.414v1.561h.046c.477-.9 1.637-1.85 3.37-1.85 3.601 0 4.267 2.37 4.267 5.455v6.286zM5.337 7.433c-1.144 0-2.063-.926-2.063-2.065 0-1.138.92-2.063 2.063-2.063 1.14 0 2.064.925 2.064 2.063 0 1.139-.925 2.065-2.064 2.065zm1.782 13.019H3.555V9h3.564v11.452zM22.225 0H1.771C.792 0 0 .774 0 1.729v20.542C0 23.227.792 24 1.771 24h20.451C23.2 24 24 23.227 24 22.271V1.729C24 .774 23.2 0 22.222 0h.003z"/></svg>
                      <span>LinkedIn</span>
                    </button>
                    <button 
                      onClick={(e) => handleShareAction(e, 'copy')}
                      className="w-full text-left px-4 py-2 text-xs text-slate-300 hover:bg-emerald-500/10 hover:text-emerald-400 flex items-center space-x-2 transition-colors border-t border-[#30363d] mt-1 pt-2"
                    >
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 002 2h2a2 2 0 002-2M8 5a2 2 0 012-2h2a2 2 0 012 2m0 0h2a2 2 0 012 2v3m2 4H10m0 0l3-3m-3 3l3 3" />
                      </svg>
                      <span>Copiar enlace</span>
                    </button>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    </Link>
  );
};

