import React, { useState, useEffect, useRef } from 'react';
import { Link } from 'react-router-dom';
import { NewsItem } from '../types';
import OptimizedImage from './OptimizedImage';

interface NewsCardProps {
  news: NewsItem;
}

const NewsCard: React.FC<NewsCardProps> = ({ news }) => {
  const [isVisible, setIsVisible] = useState(false);
  const cardRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
          observer.unobserve(entry.target);
        }
      },
      { threshold: 0.1 }
    );
    if (cardRef.current) observer.observe(cardRef.current);
    return () => observer.disconnect();
  }, []);

  return (
    <Link to={`/news/${news.id}`} className="group block bg-[#121212] border border-[#222] hover:border-red-600 transition-all duration-300 h-full flex flex-col">
      <div className="relative h-48 overflow-hidden bg-[#1a1a1a]">
        {!isVisible && <div className="absolute inset-0 shimmer" />}
        <img 
          src={news.imageUrl} 
          alt={news.title} 
          className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110" 
        />
        <div className="absolute top-0 right-0 p-2">
           <span className="bg-red-600 text-white text-[8px] font-black px-2 py-0.5 uppercase">Análisis</span>
        </div>
        <div className="absolute bottom-0 left-0 p-2 bg-black/80 text-[8px] font-black text-white uppercase tracking-tighter">
          {news.category}
        </div>
      </div>
      <div className="p-5 flex flex-col flex-grow">
        <h3 className="text-lg font-black text-white leading-tight mb-3 group-hover:text-red-500 transition-colors">
          {news.title}
        </h3>
        <p className="text-slate-500 text-xs line-clamp-2 leading-relaxed mb-4">
          {news.excerpt}
        </p>
        <div className="mt-auto pt-4 border-t border-[#222] flex justify-between items-center text-[10px] font-bold uppercase tracking-widest text-slate-500">
           <span>{news.author}</span>
           <span>{news.date}</span>
        </div>
      </div>
    </Link>
  );
};

